from scipy.optimize import least_squares
def mk(p, kind):
    w,q,e=p
    if kind==0: X=np.c_[np.sin(w*t)*P, np.sqrt(P)*t**q]
    if kind==1: X=np.c_[np.sin(w*t)*P, t**q, np.sqrt(P)]
    if kind==2: X=np.c_[np.sin(w*t)*P, t**q*P, P**e]
    if kind==3: X=np.c_[np.sin(w*t)*P, t**q, P**e]
    return X
def resid(p,kind):
    X=mk(p,kind)
    cc=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return dP_dt-X@cc
